\begin{theorem}[Pointwise $1/4$-pinched manifolds are space forms]
\label{thm:chow-ii-appd-quarter-pinched-space-form}
\source{chow-et-al-ricci-flow-part-ii:page-0386}
\dcref{appD:D.10}
\group{Ricci Flow Convergence}

If a closed Riemannian manifold satisfies
$K_{\min}(x)>\frac14K_{\max}(x)>0$ at every point, then it is diffeomorphic
to a spherical space form and admits a metric of constant positive sectional
curvature.
\end{theorem}

